/bin/bash -lc "cat > /tmp/pty_test.py <<'PY'
import os, pty, select, time, sys
pid, fd = pty.fork()
if pid == 0:
    os.environ['TERM'] = 'xterm-256color'
    os.execvp('python3', ['python3', '/workspace/neon_snake.py'])
else:
    buf = b''
    deadline = time.time() + 1.5
    while time.time() < deadline:
        r, _, _ = select.select([fd], [], [], 0.1)
        if r:
            try:
                chunk = os.read(fd, 8192)
            except OSError:
                break
            if not chunk:
                break
            buf += chunk
    # Send 'q' to quit cleanly.
    try:
        os.write(fd, b'q')
    except OSError:
        pass
    # Drain a bit.
    deadline = time.time() + 0.5
    while time.time() < deadline:
        r, _, _ = select.select([fd], [], [], 0.1)
        if r:
            try:
                chunk = os.read(fd, 8192)
            except OSError:
                break
            if not chunk:
                break
            buf += chunk
    pid_done, status = os.waitpid(pid, os.WNOHANG)
    if pid_done == 0:
        try: os.kill(pid, 9)
        except ProcessLookupError: pass
        os.waitpid(pid, 0)
    print(\"--- captured\", len(buf), \"bytes ---\")
    # Look for the HUD text or border glyphs.
    has_score = b'SCORE' in buf
    has_border = b'-=-' in buf or b'|' in buf
    has_snake = b'>' in buf or b'"'^'"' in buf or b'v' in buf or b'<' in buf
    print(\"has_score_line:\", has_score)
    print(\"has_border:    \", has_border)
    print(\"has_snake:     \", has_snake)
    print(\"clean_exit:    \", pid_done "'!= 0)
PY
python3 /tmp/pty_test.py'

